    ok("department row shows head and count", "Yaw Ofori" in drow().inner_text() and "1" in drow().locator(".dept-count-pill").inner_text())
    pg.goto(B+"/hr/employees", wait_until="networkidle"); pg.wait_for_selector("text=Kofi Asante", timeout=15000)
    opt=pg.locator("#Department option", has_text=dname).get_attribute("value"); pg.select_option("#Department", opt); time.sleep(.3)
    ok("employee list filters by department", pg.locator(".employee-table tbody tr").count()==1 and "Yaw Ofori" in pg.locator(".employee-table tbody").inner_text())
    pg.goto(B+"/hr", wait_until="networkidle"); pg.wait_for_selector(f".dept-list >> text={dname}", timeout=15000)
    ok("HR dashboard headcount uses real departments", True)
    pg.goto(B+"/hr/departments", wait_until="networkidle"); pg.wait_for_selector(f".departments-table >> text={dname}")
    drow().locator("button.view-dept").click(); dlg=pg.locator("[role=dialog]"); dlg.wait_for()
